mapper.select:
select * from orders


        and order_number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and coach_id = #{coachId}


        and status = #{status}


        and submit_time >= #{beginTime}


        and submit_time <= #{endTime}


order by submit_time desc

select sum(amount)
from orders


        and submit_time > #{begin}


        and submit_time < #{end}


        and status = #{status}

select count(id)
from orders


        and submit_time > #{begin}


        and submit_time < #{end}


        and status = #{status}

select od.name,sum(od.number) number from order_detail od ,orders o where od.order_id = o.id and o.status = 5
and o.submit_time > #{begin}
and o.submit_time < #{end}
group by od.name order by number desc limit 0,10
